class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Determine the maximum value to size our arrays
        # This ensures we cover all possible values in groups and elements
        max_val = 0
        if groups:
            max_val = max(max_val, max(groups))
        if elements:
            max_val = max(max_val, max(elements))

        # If max_val is 0 (should not happen per constraints), handle gracefully
        if max_val == 0:
            return [-1] * len(groups)

        # first_occurrence[v] stores the smallest index j such that elements[j] == v
        # Initialize with -1 to indicate not found
        first_occurrence = [-1] * (max_val + 1)
        for idx, val in enumerate(elements):
            if first_occurrence[val] == -1:
                first_occurrence[val] = idx

        # Collect candidates (value, index) for values present in elements
        candidates = []
        for val in range(1, max_val + 1):
            if first_occurrence[val] != -1:
                candidates.append((val, first_occurrence[val]))

        # Sort candidates by index to ensure we process smaller indices first.
        # This allows us to set best_element_index only once per multiple.
        candidates.sort(key=lambda x: x[1])

        # best_element_index[v] stores the smallest index j such that elements[j] divides v
        # Initialize with -1 to indicate no suitable element found
        best_element_index = [-1] * (max_val + 1)

        for val, idx in candidates:
            # Iterate through multiples of val up to max_val
            # This is similar to the Sieve of Eratosthenes
            for multiple in range(val, max_val + 1, val):
                if best_element_index[multiple] == -1:
                    best_element_index[multiple] = idx

        # Build the result array
        result = []
        for g in groups:
            result.append(best_element_index[g])

        return result

