class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Precompute sets for intersection calculation
        row_sets = [set(row) for row in properties]

        # DSU initialization
        parent = list(range(n))

        def find(i):
            if parent[i] != i:
                parent[i] = find(parent[i])
            return parent[i]

        def union(i, j):
            root_i = find(i)
            root_j = find(j)
            if root_i != root_j:
                parent[root_i] = root_j
                return True
            return False

        # Build graph / Union sets
        for i in range(n):
            for j in range(i + 1, n):
                # Calculate intersection size
                common = len(row_sets[i] & row_sets[j])
                if common >= k:
                    union(i, j)

        # Count connected components
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1

        return components

if __name__ == "__main__":
