def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        H = int(next(iterator))
        W = int(next(iterator))
        D = int(next(iterator))
    except StopIteration:
        return

    grid = []
    for _ in range(H):
        try:
            grid.append(next(iterator))
        except StopIteration:
            break

    # Distance array to store minimum distance from any humidifier
    # Initialize with -1 to represent unvisited
    dist = [[-1] * W for _ in range(H)]
    queue = deque()

    # Initialize BFS with all humidifier positions
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 'H':
                dist[r][c] = 0
                queue.append((r, c))

    # Directions for moving up, down, left, right
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # BFS traversal
    while queue:
        r, c = queue.popleft()
        d = dist[r][c]

        # If current distance is D, we don't need to expand further
        # because neighbors would be at distance D+1, which is > D.
        # We only care about cells with distance <= D.
        if d == D:
            continue

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            # Check boundaries
            if 0 <= nr < H and 0 <= nc < W:
                # Check if not a wall and not visited
                if grid[nr][nc] != '#' and dist[nr][nc] == -1:
                    dist[nr][nc] = d + 1
                    queue.append((nr, nc))

    # Count humidified floor cells
    # A cell is humidified if it is not a wall and dist <= D
    # dist != -1 ensures it was reached from a humidifier
    count = 0
    for r in range(H):
        for c in range(W):
            if grid[r][c] != '#' and dist[r][c] != -1 and dist[r][c] <= D:
                count += 1

    print(count)

if __name__ == '__main__':
    solve()
