def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        X = int(next(iterator))
        A = [int(next(iterator)) for _ in range(N)]
        B = [int(next(iterator)) for _ in range(N)]
        P = [int(next(iterator)) for _ in range(N)]
        Q = [int(next(iterator)) for _ in range(N)]
    except StopIteration:
        return

    # Convert to 0-based
    X -= 1
    P = [p - 1 for p in P]
    Q = [q - 1 for q in Q]

    # Compute P_inv and Q_inv
    P_inv = [0] * N
    Q_inv = [0] * N
    for i in range(N):
        P_inv[P[i]] = i
        Q_inv[Q[i]] = i

    # Compute dist_P
    dist_P = [-1] * N
    c_p_nodes = []
    curr = X
    while True:
        c_p_nodes.append(curr)
        curr = P_inv[curr]
        if curr == X:
            break

    for i, node in enumerate(c_p_nodes):
        dist_P[node] = i

    # Check red balls
    D_R = -1
    possible = True
    for i in range(N):
        if A[i] == 1:
            if dist_P[i] == -1:
                possible = False
                break
            if dist_P[i] > D_R:
                D_R = dist_P[i]

    if not possible:
        print(-1)
        return

    # Compute dist_Q
    dist_Q = [-1] * N
    c_q_nodes = []
    curr = X
    while True:
        c_q_nodes.append(curr)
        curr = Q_inv[curr]
        if curr == X:
            break

    for i, node in enumerate(c_q_nodes):
        dist_Q[node] = i

    # Check blue balls
    D_B = -1
    for i in range(N):
        if B[i] == 1:
            if dist_Q[i] == -1:
                possible = False
                break
            if dist_Q[i] > D_B:
                D_B = dist_Q[i]

    if not possible:
        print(-1)
        return

    # Identify U
    U = set()
    in_U_R = [False] * N
    in_U_B = [False] * N

    for u in c_p_nodes:
        if dist_P[u] <= D_R:
            in_U_R[u] = True
            if u != X:
                U.add(u)

    for u in c_q_nodes:
        if dist_Q[u] <= D_B:
            in_U_B[u] = True
            if u != X:
                U.add(u)

    if not U:
        print(0)
        return

    # Build dependency graph
    adj = [[] for _ in range(N)]

    for u in U:
        # Add P-edge
        if in_U_R[u] and dist_P[u] > 1:
            v = P[u]
            adj[u].append(v)

        # Add Q-edge
        if in_U_B[u] and dist_Q[u] > 1:
            v = Q[u]
            adj[u].append(v)

    # Cycle detection
    state = [0] * N # 0: unvisited, 1: visiting, 2: visited
    has_cycle = False

    def dfs(u):
        nonlocal has_cycle
        state[u] = 1
        for v in adj[u]:
            if state[v] == 1:
                has_cycle = True
                return
            if state[v] == 0:
                dfs(v)
                if has_cycle:
                    return
        state[u] = 2

    for u in U:
        if state[u] == 0:
            dfs(u)
            if has_cycle:
                break

    if has_cycle:
        print(-1)
    else:
        print(len(U))

