import sys

class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Mapping: F -> 0, W -> 1, E -> 2
        # Rules:
        # F (0) beats E (2)
        # W (1) beats F (0)
        # E (2) beats W (1)
        # So x beats (x+2)%3
        # Bob wins if b beats a => b = (a+1)%3
        # Bob loses if b loses to a => b = (a+2)%3
        # Tie if b = a

        # DP state: dp[last_move][diff + n]
        # last_move: 0, 1, 2
        # diff: -n to n, offset by n -> 0 to 2n

        # Initialize DP
        dp = [[0] * (2 * n + 1) for _ in range(3)]

        # Base case i = 0
        a0 = {'F': 0, 'W': 1, 'E': 2}[s[0]]

        for m in range(3):
            if m == (a0 + 1) % 3:
                d = 1
            elif m == (a0 + 2) % 3:
                d = -1
            else:
                d = 0
            dp[m][n + d] = 1

        # Iterate
        for i in range(1, n):
            new_dp = [[0] * (2 * n + 1) for _ in range(3)]
            ai = {'F': 0, 'W': 1, 'E': 2}[s[i]]

            # Valid range for diff index in dp (from round i-1)
            # Max diff after i-1 rounds is i.
            # So indices [n-i, n+i]
            min_diff_idx = n - i
            max_diff_idx = n + i

            for prev_m in range(3):
                for diff_idx in range(min_diff_idx, max_diff_idx + 1):
                    count = dp[prev_m][diff_idx]
                    if count == 0:
                        continue

                    for curr_m in range(3):
                        if curr_m == prev_m:
                            continue

                        # Calculate d for curr_m
                        if curr_m == (ai + 1) % 3:
                            d = 1
                        elif curr_m == (ai + 2) % 3:
                            d = -1
                        else:
                            d = 0

                        new_diff_idx = diff_idx + d
                        if 0 <= new_diff_idx <= 2 * n:
                            new_dp[curr_m][new_diff_idx] = (new_dp[curr_m][new_diff_idx] + count) % MOD

            dp = new_dp

        # Sum up results where diff > 0
        ans = 0
        for m in range(3):
            for diff_idx in range(n + 1, 2 * n + 1):
                ans = (ans + dp[m][diff_idx]) % MOD

        return ans

if __name__ == "__main__":
    try:
        s = input().strip()
        # Handle potential "s = " prefix or quotes
        if '=' in s:
            s = s.split('=')[1].strip()
        if s.startswith('"') and s.endswith('"'):
            s = s[1:-1]
        elif s.startswith("'") and s.endswith("'"):
            s = s[1:-1]

        solution = Solution()
        result = solution.countWinningSequences(s)
        print(result)
    except EOFError:
        pass
