sys.setrecursionlimit(2000)

MOD = 10**9 + 7

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        L = len(s)

        # Precompute combinations C[n][r] modulo MOD
        # C[n][r] = nCr
        C = [[0] * (L + 1) for _ in range(L + 1)]
        for i in range(L + 1):
            C[i][0] = 1
            for j in range(1, i + 1):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD

        def count_with_popcount(c):
            # Count numbers x < n (represented by s) with exactly c set bits
            if c < 1 or c > L:
                return 0
            ans = 0
            cnt = 0
            for i in range(L):
                if s[i] == '1':
                    rem = L - 1 - i
                    needed = c - cnt
                    if needed >= 0:
                        # C[rem][needed] is 0 if needed > rem, which is correct
                        ans = (ans + C[rem][needed]) % MOD
                    cnt += 1
            return ans

        # Compute the set of valid popcounts for the (k-1)-th reduction step
        # We need to count x < n such that f(x) is (k-1)-reducible.
        # Let R_j be the set of j-reducible numbers.
        # We need to count x < n such that f(x) in R_{k-1}.
        # Since f(x) <= L, we only care about R_{k-1} intersect {1, ..., L}.
        # R_0 = {1}
        # R_j = {v | f(v) in R_{j-1}}

        Valid = {1}
        for _ in range(k - 1):
            NewValid = set()
            for v in range(1, L + 1):
                if bin(v).count('1') in Valid:
                    NewValid.add(v)
            Valid = NewValid

        ans = 0
        for c in Valid:
            ans = (ans + count_with_popcount(c)) % MOD

        return ans

if __name__ == "__main__":
