    try:
        s_line = sys.stdin.readline().strip()
        if not s_line:
            # Handle potential empty input gracefully
            pass
        else:
            # Remove quotes if present (as per example format)
            if s_line.startswith('"') and s_line.endswith('"'):
                s = s_line[1:-1]
            else:
                s = s_line

            k_line = sys.stdin.readline().strip()
            if k_line:
                k = int(k_line)
            else:
                k = 0 # Should not happen based on constraints

            sol = Solution()
            result = sol.countKReducibleNumbers(s, k)
            print(result)
