class Solution:
    def countValidSelections(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Identify all starting positions where nums[i] == 0
        start_positions = [i for i, x in enumerate(nums) if x == 0]

        for start in start_positions:
            for direction in [-1, 1]:
                # Make a copy of nums to simulate
                current_nums = nums[:]
                curr = start
                d = direction

                # Calculate initial sum
                current_sum = sum(current_nums)

                # If already all zeros, it's valid (will eventually go out of bounds)
                if current_sum == 0:
                    count += 1
                    continue

                # Simulate the process
                while 0 <= curr < n:
                    if current_nums[curr] == 0:
                        curr += d
                    else:
                        current_nums[curr] -= 1
                        current_sum -= 1
                        d = -d
                        curr += d

                    # Optimization: if sum becomes 0, we are guaranteed to succeed
                    if current_sum == 0:
                        break

                if current_sum == 0:
                    count += 1

        return count

if __name__ == "__main__":
