from typing import List

class Solution:
    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        # dp[i][j] stores the maximum reduction possible using at most i Op1s and j Op2s
        # Initialize with 0 because 0 reduction is always possible (by doing nothing)
        dp = [[0] * (op2 + 1) for _ in range(op1 + 1)]

        for x in nums:
            # Iterate backwards to ensure each item is used at most once per state
            for i in range(op1, -1, -1):
                for j in range(op2, -1, -1):
                    # Option 1: Apply Operation 1 (Divide by 2, round up)
                    # Cost: 1 Op1, 0 Op2
                    if i + 1 <= op1:
                        val = x - (x + 1) // 2
                        if dp[i][j] + val > dp[i+1][j]:
                            dp[i+1][j] = dp[i][j] + val

                    # Option 2: Apply Operation 2 (Subtract k)
                    # Cost: 0 Op1, 1 Op2
                    # Condition: nums[i] >= k
                    if j + 1 <= op2 and x >= k:
                        val = k
                        if dp[i][j] + val > dp[i][j+1]:
                            dp[i][j+1] = dp[i][j] + val

                    # Option 3: Apply Both Operations
                    # Cost: 1 Op1, 1 Op2
                    # Order matters. Op1 then Op2 is generally better.
                    # Op1 then Op2: ceil(x/2) - k. Valid if ceil(x/2) >= k.
                    # Op2 then Op1: ceil((x-k)/2). Valid if x >= k.
                    if i + 1 <= op1 and j + 1 <= op2:
                        # Check Op1 then Op2
                        if (x + 1) // 2 >= k:
                            val = x - ((x + 1) // 2 - k)
                            if dp[i][j] + val > dp[i+1][j+1]:
                                dp[i+1][j+1] = dp[i][j] + val
                        # Check Op2 then Op1 (only if Op1 then Op2 is not valid)
                        elif x >= k:
                            val = x - ((x - k + 1) // 2)
                            if dp[i][j] + val > dp[i+1][j+1]:
                                dp[i+1][j+1] = dp[i][j] + val

        # Find the maximum reduction possible within the limits
        max_reduction = 0
        for i in range(op1 + 1):
            for j in range(op2 + 1):
                if dp[i][j] > max_reduction:
                    max_reduction = dp[i][j]

        return sum(nums) - max_reduction

if __name__ == "__main__":
    # Read input from stdin
    try:
        line1 = sys.stdin.readline()
