class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        max_time = -1
        result_index = -1
        prev_time = 0

        for i, (index, time) in enumerate(events):
            if i == 0:
                time_taken = time
            else:
                time_taken = time - prev_time

            if time_taken > max_time:
                max_time = time_taken
                result_index = index
            elif time_taken == max_time:
                if index < result_index:
                    result_index = index

            prev_time = time

        return result_index

